import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import { useAppContext } from "../context/AppContext";
import api from "../services/api";

// ✅ SAFE TOKEN PARSE
const getRoleFromToken = (token) => {
  try {
    if (!token) return null;

    const base64 = token.split(".")[1];
    if (!base64) return null;

    const payload = JSON.parse(atob(base64));
    return payload?.role || null;
  } catch {
    return null;
  }
};

const Login = () => {
  const navigate = useNavigate();
  const { preloadAfterLogin } = useAppContext();

  const [formData, setFormData] = useState({
    username: "",
    password: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // ✅ AUTO REDIRECT (SAFE)
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (token && token !== "null" && token !== "undefined") {
      const role = getRoleFromToken(token);

      if (role === "admin") navigate("/admin", { replace: true });
      else if (role === "client") navigate("/client", { replace: true });
      else {
        // ❌ invalid token cleanup
        localStorage.removeItem("token");
        localStorage.removeItem("user");
      }
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    setError("");
    setLoading(true);

    try {
      const res = await api.post("/auth/login", formData);

      // ✅ TOKEN SAFE EXTRACT
      const token = res?.data?.access_token;

      if (!token) {
        throw new Error("Invalid login response");
      }

      const role = getRoleFromToken(token);

      if (!role) {
        throw new Error("Invalid token");
      }

      const userData = res.data.user || {
        username: formData.username,
        role,
      };

      // ✅ CLEAR OLD TOKEN (IMPORTANT)
      localStorage.removeItem("token");
      localStorage.removeItem("user");

      // ✅ SAVE NEW TOKEN
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(userData));

      // ✅ NAVIGATION
      if (role === "admin") {
        navigate("/admin", { replace: true });
      } else {
        navigate("/client", { replace: true });
      }

      // ✅ PREFETCH (NON-BLOCKING)
      setTimeout(() => {
        preloadAfterLogin?.(role);
      }, 0);

    } catch (err) {
      console.log("LOGIN ERROR:", err);

      const msg =
        typeof err.response?.data?.detail === "object"
          ? JSON.stringify(err.response.data.detail)
          : err.response?.data?.detail ||
            err.message ||
            "Server not reachable";

      setError(msg);

      // ❌ CLEANUP ON ERROR
      localStorage.removeItem("token");
      localStorage.removeItem("user");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell">
      <div className="auth-hero">
        <p className="eyebrow">College Resource Booking</p>
        <h1>Book labs, halls & resources instantly</h1>
        <p>Fast, simple and optimized booking system.</p>
      </div>

      <div className="auth-card">
        <h2>Sign In</h2>
        <p>Use your account credentials to continue.</p>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            <span>Username</span>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </label>

          <label>
            <span>Password</span>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </label>

          {/* ✅ ERROR SAFE */}
          {error && (
            <div className="alert error">
              {typeof error === "object"
                ? JSON.stringify(error)
                : error}
            </div>
          )}

          <button
            type="submit"
            className="primary-button auth-button"
            disabled={loading}
          >
            {loading ? "Logging in..." : "Login"}
          </button>
        </form>

        <p className="auth-link">
          New user? <Link to="/register">Create an account</Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
